import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	dir := os.Args[1]
	files, _ := filepath.Glob(filepath.Join(dir, "*.go"))
	fs := token.NewFileSet()
	for _, f := range files {
		if strings.HasSuffix(f, "_test.go") {
			continue
		}
		af, err := parser.ParseFile(fs, f, nil, parser.ParseComments)
		if err != nil {
			continue
		}
		tf := fs.File(af.Pos())
		fmt.Printf("FILE\t%s\t%d\n", filepath.Base(f), tf.LineCount())
		for _, d := range af.Decls {
			start := d.Pos()
			var name string
			switch x := d.(type) {
			case *ast.FuncDecl:
				name = x.Name.Name
				if x.Recv != nil && len(x.Recv.List) > 0 {
					name = "(recv)." + name
				}
				if x.Doc != nil {
					start = x.Doc.Pos()
				}
				body := fs.Position(x.End()).Line - fs.Position(x.Pos()).Line + 1
				fmt.Printf("FUNC\t%s\t%s\t%d\t%d\t%d\n", filepath.Base(f), name, fs.Position(x.Pos()).Line, body, fs.Position(x.End()).Line-fs.Position(start).Line+1)
			case *ast.GenDecl:
				if x.Doc != nil {
					start = x.Doc.Pos()
				}
				for _, s := range x.Specs {
					switch sp := s.(type) {
					case *ast.TypeSpec:
						name = sp.Name.Name
					case *ast.ValueSpec:
						name = sp.Names[0].Name
					}
					fmt.Printf("DECL\t%s\t%s\t%d\t%d\t%d\n", filepath.Base(f), name, fs.Position(s.Pos()).Line, fs.Position(s.End()).Line-fs.Position(s.Pos()).Line+1, fs.Position(x.End()).Line-fs.Position(start).Line+1)
				}
			}
		}
	}
}
EOF
