package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

func main() {
	dir := os.Args[1]
	var names []string
	sc := bufio.NewScanner(os.Stdin)
	for sc.Scan() {
		names = append(names, regexp.QuoteMeta(sc.Text()))
	}
	re := regexp.MustCompile(`\b(` + strings.Join(names, "|") + `)\b`)
	files, _ := filepath.Glob(filepath.Join(dir, "*_test.go"))
	fs := token.NewFileSet()
	total := 0
	per := map[string]int{}
	for _, f := range files {
		src, _ := os.ReadFile(f)
		af, err := parser.ParseFile(fs, f, src, parser.ParseComments)
		if err != nil {
			continue
		}
		for _, d := range af.Decls {
			fd, ok := d.(*ast.FuncDecl)
			if !ok {
				continue
			}
			s := fs.Position(fd.Pos()).Offset
			e := fs.Position(fd.End()).Offset
			if re.Match(src[s:e]) {
				n := fs.Position(fd.End()).Line - fs.Position(fd.Pos()).Line + 1
				total += n
				per[filepath.Base(f)] += n
			}
		}
	}
	for k, v := range per {
		fmt.Println(v, k)
	}
	fmt.Println("TOTAL", total)
}
EOF
